import numpy as np

def chunk_text(text, chunk_size=500, overlap=50):
    words = text.split()
    chunks = []
    start = 0
    while start < len(words):
        end = start + chunk_size
        chunks.append(" ".join(words[start:end]))
        start = end - overlap
    return chunks

def cosine_similarity(a, b):
    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))

class SimpleRAGPipeline:
    def __init__(self, embed_fn):
        self.embed_fn = embed_fn  # function: str -> np.ndarray
        self.chunks = []
        self.embeddings = []
        self.sources = []

    def index_documents(self, documents):
        for doc_id, text in enumerate(documents):
            for chunk in chunk_text(text):
                self.chunks.append(chunk)
                self.embeddings.append(self.embed_fn(chunk))
                self.sources.append(doc_id)

    def retrieve(self, query, top_k=3):
        query_vec = self.embed_fn(query)
        scores = [cosine_similarity(query_vec, emb) for emb in self.embeddings]
        top_indices = np.argsort(scores)[::-1][:top_k]
        return [(self.chunks[i], self.sources[i], scores[i]) for i in top_indices]

    def build_prompt(self, query, top_k=3):
        retrieved = self.retrieve(query, top_k)
        context_block = "\n\n".join(
            f"[Source {src}] {chunk}" for chunk, src, _ in retrieved
        )
        return (
            "Answer the question using ONLY the context below. "
            "If the context does not contain the answer, say so explicitly.\n\n"
            f"CONTEXT:\n{context_block}\n\n"
            f"QUESTION: {query}"
        )

