import json
import re
from pydantic import BaseModel, ValidationError, field_validator
from datetime import date

class InvoiceExtraction(BaseModel):
    invoice_number: str
    vendor_name: str
    total_amount: float
    due_date: date

    @field_validator("total_amount", mode="before")
    @classmethod
    def strip_currency_symbols(cls, v):
        if isinstance(v, str):
            return float(re.sub(r"[^0-9.]", "", v))
        return v

EXTRACTION_PROMPT = """Extract the following fields from the invoice text as JSON only,
with no explanation and no markdown formatting:
{{"invoice_number": string, "vendor_name": string, "total_amount": number, "due_date": "YYYY-MM-DD"}}

Invoice text:
{invoice_text}
"""

def extract_invoice_fields(invoice_text, llm_call_fn, max_retries=1):
    prompt = EXTRACTION_PROMPT.format(invoice_text=invoice_text)

    for attempt in range(max_retries + 1):
        raw_output = llm_call_fn(prompt)

        # Defensively strip markdown code fences if the model added them anyway
        cleaned = re.sub(r"^```(json)?|```$", "", raw_output.strip(), flags=re.MULTILINE).strip()

        try:
            parsed = json.loads(cleaned)
            validated = InvoiceExtraction(**parsed)
            return validated
        except (json.JSONDecodeError, ValidationError) as e:
            if attempt == max_retries:
                return {"error": str(e), "raw_output": raw_output, "needs_human_review": True}
            prompt += "\n\nYour previous response was invalid JSON or missing required fields. Return ONLY valid JSON matching the schema exactly."

    return None
